'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),crypto=require('node:crypto');
const {inspectSurface}=require('../src/native-surface.cjs'),{childEnv,FINDER_PATH}=require('../src/policy.cjs');
const boot='http://127.0.0.1:32100/?token=fixture-launch-token',source=Buffer.from('// fixture whale source\nwindow.fixtureSkin=true;\n');
function protocol({skin=true,skinId='dsh-ui-skin',moduleUrl='/plugins/?id='+encodeURIComponent(skinId)+'&rev=fixture',script=Buffer.concat([source,Buffer.from(';\n//# sourceMappingURL=fixture.map\n')]),count=36}={}){
 const calls=[],responses=[new Response(null,{status:303,headers:{'Set-Cookie':'fixture-session=private; HttpOnly; SameSite=Strict'}}),Response.json({ok:true,value:{total:count,items:Array.from({length:count},()=>({image:'data:image/webp;base64,fixture'}))}}),new Response('<script>globalThis["__DSH_BOOT__"] = '+JSON.stringify({modules:skin?[{id:skinId,url:moduleUrl}]:[]})+'</script>'),new Response(script,{headers:{'Content-Type':'text/javascript'}})];
 const request=async(url,options)=>{calls.push({url:new URL(url),options});assert(responses.length,'Unexpected extra request');return responses.shift();};return{calls,request};
}
test('native protocol inspection checks avatar, graph URL and exact skin body without executing it',async()=>{const mock=protocol(),result=await inspectSurface(boot,source,mock.request);assert.equal(result.total,36);assert.equal(result.nativeSkinModuleId,'dsh-ui-skin');assert.equal(result.skinSourceSha256,crypto.createHash('sha256').update(source).digest('hex'));assert.equal(result.nativeComboContainsExactSkinSource,true);assert.equal(result.scriptExecuted,false);assert.equal(result.browserOpened,false);assert.equal(mock.calls.length,4);assert.equal(mock.calls[0].options.redirect,'manual');assert.equal(mock.calls[3].url.href,'http://127.0.0.1:32100/plugins/?id=dsh-ui-skin&rev=fixture');assert.equal(mock.calls[3].options.headers.Cookie,'fixture-session=private');assert.equal(JSON.parse(mock.calls[1].options.body).endpoint,'avatar-library');});
test('configured Cordis ui-skin ID also resolves its native graph URL and exact installed source',async()=>{const mock=protocol({skinId:'ui-skin'}),result=await inspectSurface(boot,source,mock.request);assert.equal(result.nativeSkinModuleId,'ui-skin');assert.equal(result.nativeComboContainsExactSkinSource,true);assert.equal(result.skinSourceSha256,crypto.createHash('sha256').update(source).digest('hex'));assert.equal(mock.calls[3].url.href,'http://127.0.0.1:32100/plugins/?id=ui-skin&rev=fixture');assert.equal(mock.calls.length,4);});
test('native graph must actually register the whale package',async()=>{const mock=protocol({skin:false});await assert.rejects(inspectSurface(boot,source,mock.request),/not registered/);assert.equal(mock.calls.length,3);});
test('neither legal ID forwards a session to an external or different local origin',async()=>{for(const skinId of ['ui-skin','dsh-ui-skin'])for(const moduleUrl of ['https://example.invalid/skin.js','http://127.0.0.1:9/skin.js','http://u:p@127.0.0.1:32100/skin.js']){const mock=protocol({skinId,moduleUrl});await assert.rejects(inspectSurface(boot,source,mock.request),/local authenticated URL|changed origin/);assert.equal(mock.calls.length,3);}});
test('neither legal ID permits changed or truncated skin content',async()=>{for(const skinId of ['ui-skin','dsh-ui-skin'])for(const script of [Buffer.from('// a different skin'),source.subarray(0,-3)]){const mock=protocol({skinId,script});await assert.rejects(inspectSurface(boot,source,mock.request),/omitted or changed/);assert.equal(mock.calls.length,4);}});
test('unrelated skin-like IDs are not accepted',async()=>{for(const skinId of ['other-skin','ui-skin-copy']){const mock=protocol({skinId});await assert.rejects(inspectSurface(boot,source,mock.request),/not registered/);assert.equal(mock.calls.length,3);}});
test('all expected avatars remain required',async()=>{const mock=protocol({count:35});await assert.rejects(inspectSurface(boot,source,mock.request),/36 seeded/);assert.equal(mock.calls.length,2);});
test('native smoke Finder PATH hides runner Node without changing the ordinary candidate environment',()=>{const parent={PATH:'/opt/hostedtoolcache/node/24/bin:/opt/homebrew/bin:/usr/bin',HOME:'/real/user',NODE_OPTIONS:'--require=private',OPENAI_API_KEY:'private',HTTP_PROXY:'private'};const smoke=childEnv('/isolated',parent,{finderPath:true});assert.equal(smoke.PATH,'/usr/bin:/bin:/usr/sbin:/sbin');assert.equal(smoke.PATH,FINDER_PATH);assert.equal(childEnv('/isolated',parent).PATH,parent.PATH);for(const name of ['NODE_OPTIONS','OPENAI_API_KEY','HTTP_PROXY'])assert(!(name in smoke));assert.equal(smoke.DSH_HOME,'/isolated');});
